   205	function signOutAndRedirectToSignIn(shouldResetToHome?: boolean, shouldStashSession?: boolean, killHybridApp = true) {
   206	    Log.info('Redirecting to Sign In because signOut() was called');
   207	    hideContextMenu(false);
   208	    if (!isAnonymousUser()) {
   209	        // In the HybridApp, we want the Old Dot to handle the sign out process
   210	        if (NativeModules.HybridAppModule && killHybridApp) {
   211	            NativeModules.HybridAppModule.closeReactNativeApp(true, false);
   212	            return;
   213	        }
   214	        // We'll only call signOut if we're not stashing the session and this is not a supportal session,
   215	        // otherwise we'll call the API to invalidate the autogenerated credentials used for infinite
   216	        // session.
   217	        const isSupportal = isSupportAuthToken();
   218	        if (!isSupportal && !shouldStashSession) {
   219	            signOut();
   220	        }
   221	
   222	        // The function redirectToSignIn will clear the whole storage, so let's create our onyx params
   223	        // updates for the credentials before we call it
   224	        let onyxSetParams = {};
   225	
   226	        // If we are not currently using a support token, and we received stashSession as true, we need to
   227	        // store the credentials so the user doesn't need to login again after they finish their supportal
   228	        // action. This needs to computed before we call `redirectToSignIn`
   229	        if (!isSupportal && shouldStashSession) {
   230	            onyxSetParams = {
   231	                [ONYXKEYS.STASHED_CREDENTIALS]: credentials,
   232	                [ONYXKEYS.STASHED_SESSION]: session,
   233	            };
   234	        }
   235	        // If this is a supportal token, and we've received the parameters to stashSession as true, and
   236	        // we already have a stashedSession, that means we are supportaled, currently supportaling
   237	        // into another account and we want to keep the stashed data from the original account.
   238	        if (isSupportal && shouldStashSession && hasStashedSession()) {
   239	            onyxSetParams = {
   240	                [ONYXKEYS.STASHED_CREDENTIALS]: stashedCredentials,
   241	                [ONYXKEYS.STASHED_SESSION]: stashedSession,
   242	            };
   243	        }
