function checkIfActionIsAllowed<TCallback extends ((...args: any[]) => any) | void>(callback: TCallback, isAnonymousAction = false): TCallback | (() => void) {
    // If the user is offline, let the action run since we will be showing an offline indicator and prompting them to sign in when they come back online
    if (isAnonymousUser() && !isAnonymousAction && !NetworkStore.isOffline()) {
        signOutAndRedirectToSignIn();
        return () => {};
    }
    return callback;
}

